THOUGHT: The error comes from the remote detection backend (gradio client) returning an unexpected response (None), causing detection(...) to raise. I'll add robust try/except around detection calls, check outputs before using them, and fall back to sliding_window_detection when the global detector fails or returns no boxes. This prevents the TypeError and lets us continue searching and displaying possible detections safely.

ACTION:
```python
# python
# Robust detection with exception handling and safe fallbacks to sliding_window_detection.
# This fixed code avoids using outputs when they are None and handles remote errors gracefully.

def safe_detection(image, labels):
    try:
        result = detection(image, labels)
        # detection may return None or malformed outputs; validate it
        if result is None:
            print(f"detection(...) returned None for labels {labels}")
            return None, []
        anno_img, boxes = result
        if anno_img is None:
            print(f"detection(...) returned no annotated image for labels {labels}")
        if boxes is None:
            print(f"detection(...) returned no boxes for labels {labels}")
            boxes = []
        return anno_img, boxes
    except Exception as e:
        print(f"Error during detection for labels {labels}: {e}")
        return None, []

# 1) Try global detection for toy soldiers / fighters
print("Running detection for 'toy soldier' and 'fighter'...")
toy_anno, toy_boxes = safe_detection(image_1, ["toy soldier", "fighter"])
if toy_anno is not None:
    display(toy_anno.annotated_image)
print("Detected toy/fighter boxes:", toy_boxes)

# 2) Try global detection for rubber objects
print("\nRunning detection for 'rubber' objects...")
rubber_anno, rubber_boxes = safe_detection(image_1, ["rubber"])
if rubber_anno is not None:
    display(rubber_anno.annotated_image)
print("Detected rubber boxes:", rubber_boxes)

# 3) If toy/fighter not found, try sliding window search (safe)
if not toy_boxes:
    try:
        print("\nNo toy/fighter detections from global detector. Running sliding_window_detection for 'toy soldier' and 'fighter'...")
        toy_patches, toy_patch_boxes = sliding_window_detection(image_1, ["toy soldier", "fighter"])
        if toy_patches:
            for i, patch in enumerate(toy_patches):
                print(f"Toy patch {i+1}:")
                display(patch.annotated_image)
            print("Sliding-window toy/fighter boxes per patch:", toy_patch_boxes)
        else:
            print("sliding_window_detection returned no toy/fighter patches.")
    except Exception as e:
        print("Error during sliding_window_detection for toy/fighter:", e)

# 4) If rubber not found, try sliding window search (safe)
if not rubber_boxes:
    try:
        print("\nNo rubber detections from global detector. Running sliding_window_detection for 'rubber'...")
        rubber_patches, rubber_patch_boxes = sliding_window_detection(image_1, ["rubber"])
        if rubber_patches:
            for i, patch in enumerate(rubber_patches):
                print(f"Rubber patch {i+1}:")
                display(patch.annotated_image)
            print("Sliding-window rubber boxes per patch:", rubber_patch_boxes)
        else:
            print("sliding_window_detection returned no rubber patches.")
    except Exception as e:
        print("Error during sliding_window_detection for rubber:", e)

print("\nFinished detection attempts. Please inspect the displayed annotated images and patches.")
print("If you want, I can proceed to programmatically count verified boxes or zoom into each detection to confirm whether an object is metallic or rubber.") 
